const router=new Router();
const selected=(a,b)=>String(a??"")===String(b??"")?"selected":"";
function setCookie(res,v){const h=new Headers(res.headers);h.append("set-cookie",v);return new Response(res.body,{status:res.status,headers:h})}
function withCsrf(res,c){return c?.setCookie?setCookie(res,c.setCookie):res}
function denied(ctx){return html(appPage({title:"Access denied",user:ctx.user,settings:ctx.settings,active:"",url:ctx.url,content:`<div class="panel"><div class="panel-body"><h2>Permission required</h2><p class="muted">Your account cannot access this page.</p></div></div>`}),403)}
function needAuth(ctx){return ctx.user?null:redirect("/login?msg=Please+sign+in&type=error")}
function needPerm(ctx,p){return needAuth(ctx)||(can(ctx.user,p)?null:denied(ctx))}
function csrfFail(path="/"){return redirect(`${path}?msg=Security+check+failed.+Refresh+and+try+again&type=error`)}
async function context(request,env){
  await ensureSchema(env.DB);
  let user=await loadSession(env.DB,request);
  if(user)user=await hydratePermissions(env.DB,user);
  return{request,env,db:env.DB,user,settings:user?await getSettings(env.DB):{},url:new URL(request.url)};
}
async function selectOptions(db){const [b,g]=await Promise.all([db.prepare("SELECT id,name FROM batches WHERE status='ACTIVE' ORDER BY name").all(),db.prepare("SELECT id,name FROM groups_tbl WHERE status='ACTIVE' ORDER BY name").all()]);return{batches:b.results||[],groups:g.results||[]}}
function options(rows,current,key="name"){return rows.map(r=>`<option value="${r.id}" ${selected(current,r.id)}>${esc(r[key])}</option>`).join("")}
function operationError(scope,error){const id=crypto.randomUUID();console.error(scope,id,error?.stack||error);return id}
function validDateFilter(value){return /^\d{4}-\d{2}-\d{2}$/.test(value||"")&&!Number.isNaN(Date.parse(`${value}T00:00:00.000Z`))}
async function studentRelationErrors(db,{batchId,groupId}){const errors=[];let batch=null,group=null;if(batchId)batch=await db.prepare("SELECT id FROM batches WHERE id=?").bind(batchId).first();if(batchId&&!batch)errors.push("Selected batch does not exist.");if(groupId)group=await db.prepare("SELECT id,batch_id FROM groups_tbl WHERE id=?").bind(groupId).first();if(groupId&&!group)errors.push("Selected group does not exist.");if(group&&batchId&&group.batch_id&&Number(group.batch_id)!==Number(batchId))errors.push("Selected group does not belong to the selected batch.");return errors}
function methodNotAllowed(ctx,methods){const content=`<div class="panel"><div class="panel-body"><h2>405</h2><p class="muted">This page does not accept the ${esc(ctx.request.method)} method.</p></div></div>`;const headers={allow:methods.join(", ")};return ctx.user?html(appPage({title:"Method Not Allowed",user:ctx.user,settings:ctx.settings,active:"",url:ctx.url,content}),405,headers):html(authPage({title:"Method Not Allowed",subtitle:"Use one of the supported actions for this page.",content:`<a class="btn soft" href="/">Return Home</a>`,version:APP_VERSION}),405,headers)}

