router.add("POST","/students/:id/delete",async ctx=>{const deny=needPerm(ctx,"students.delete");if(deny)return deny;const id=intId(ctx.params.id),b=await readForm(ctx.request);if(!id||!checkCsrf(ctx.request,b))return csrfFail("/students");const s=await ctx.db.prepare("SELECT student_code FROM students WHERE id=?").bind(id).first();if(!s)return redirect("/students?msg=Student+not+found&type=error");await ctx.db.prepare("DELETE FROM students WHERE id=?").bind(id).run();await audit(ctx.db,ctx.user.id,"STUDENT_DELETE","student",id,s.student_code||"");return redirect("/students?msg=Student+deleted")});
