router.add("GET","/students/import",async ctx=>{const deny=needPerm(ctx,"students.import");if(deny)return deny;const csrf=csrfFor(ctx.request),content=`<div class="panel"><div class="panel-body">${notice(ctx.url)}<p class="muted">Required CSV columns: student_code, full_name. Optional: email, phone, status. Maximum ${MAX_CSV_ROWS} data rows and ${Math.floor(MAX_CSV_BYTES/1024/1024)} MB.</p><form method="post" enctype="multipart/form-data" class="grid"><label><span>CSV File</span><input type="file" name="file" accept=".csv,text/csv" required></label>${csrfField(csrf.token)}<button class="btn primary" type="submit">Import Students</button></form></div></div>`;return withCsrf(html(appPage({title:"Import Students",user:ctx.user,settings:ctx.settings,active:"students",url:ctx.url,content})),csrf)});
router.add("POST","/students/import",async ctx=>{
  const deny=needPerm(ctx,"students.import");if(deny)return deny;const b=await readForm(ctx.request);if(!checkCsrf(ctx.request,b))return csrfFail("/students/import");
  const file=b.file;if(!file||typeof file.text!=="function")return redirect("/students/import?msg=Choose+a+CSV+file&type=error");
  if(Number(file.size||0)>MAX_CSV_BYTES)return redirect("/students/import?msg=CSV+file+is+too+large&type=error");
  if(file.name&&!String(file.name).toLowerCase().endsWith(".csv"))return redirect("/students/import?msg=Only+CSV+files+are+accepted&type=error");
  const rows=parseCsv(await file.text());if(rows.length<2)return redirect("/students/import?msg=CSV+is+empty&type=error");if(rows.length-1>MAX_CSV_ROWS)return redirect(`/students/import?msg=${encodeURIComponent(`CSV exceeds the ${MAX_CSV_ROWS} row limit.`)}&type=error`);
  const h=rows[0].map(x=>clean(x,50).replace(/^﻿/,"").toLowerCase()),idx=n=>h.indexOf(n);if(idx("student_code")<0||idx("full_name")<0)return redirect("/students/import?msg=student_code+and+full_name+are+required&type=error");
  let count=0,skipped=0;const ts=nowIso();
  try{for(let start=1;start<rows.length;start+=40){const statements=[];for(const row of rows.slice(start,start+40)){const get=n=>idx(n)>=0?clean(row[idx(n)]||"",500):"",code=clean(get("student_code"),60),full=clean(get("full_name"),150),email=normalizeEmail(get("email")),status=clean(get("status"),20)||"ACTIVE";if(!code||!full||(email&&!validEmail(email))||!oneOf(status,RECORD_STATUSES)){skipped++;continue}statements.push(ctx.db.prepare("INSERT INTO students(student_code,full_name,email,phone,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(student_code) DO UPDATE SET full_name=excluded.full_name,email=excluded.email,phone=excluded.phone,status=excluded.status,updated_at=excluded.updated_at").bind(code,full,email,get("phone").slice(0,40),status,ts,ts));count++}if(statements.length)await ctx.db.batch(statements)}await audit(ctx.db,ctx.user.id,"STUDENT_IMPORT","student","",`${count} rows; ${skipped} skipped`);return redirect(`/students?msg=${encodeURIComponent(`${count} students imported${skipped?`; ${skipped} rows skipped`:""}`)}`)}
  catch(error){const ref=operationError("STUDENT_IMPORT",error);return redirect(`/students/import?msg=${encodeURIComponent(`Import failed. Reference ${ref}`)}&type=error`)}
});

router.add("GET","/students/:id",async ctx=>{
  const deny=needPerm(ctx,"students.view");if(deny)return deny;const id=intId(ctx.params.id);
  const s=id&&await ctx.db.prepare("SELECT s.*,b.name batch_name,b.code batch_code,b.status batch_status,g.name group_name,g.status group_status FROM students s LEFT JOIN batches b ON b.id=s.batch_id LEFT JOIN groups_tbl g ON g.id=s.group_id WHERE s.id=?").bind(id).first();
  if(!s)return redirect("/students?msg=Student+not+found&type=error");
  const initials=String(s.full_name||"").split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]||"").join("").toUpperCase();
  const info=(label,value,icon)=>`<div class="info-item"><i class="fi fi-rr-${icon}" aria-hidden="true"></i><div><span>${esc(label)}</span><strong>${esc(value||"—")}</strong></div></div>`;
  const actions=`<a class="btn soft" href="/students">← Students</a>${can(ctx.user,"students.edit")?`<a class="btn primary" href="/students/${id}/edit">Edit Student</a>`:""}${can(ctx.user,"students.delete")?`<a class="btn danger" href="/students/${id}/delete">Delete</a>`:""}`;
  const content=`<section class="student-hero"><div class="student-avatar" aria-hidden="true">${esc(initials||"ST")}</div><div class="student-identity"><div class="identity-top"><span class="code-pill">${esc(s.student_code)}</span>${badge(s.status)}</div><h2>${esc(s.full_name)}</h2><p>${esc(s.email||"No email address")}${s.phone?` · ${esc(s.phone)}`:""}</p></div></section><div class="profile-grid"><section class="panel"><div class="panel-head"><div><h2>Personal Information</h2><p class="panel-kicker">Core student profile details</p></div></div><div class="panel-body info-grid">${info("Student Code",s.student_code,"id-badge")}${info("Full Name",s.full_name,"user")}${info("Gender",s.gender,"users")}${info("Birth Date",s.birth_date,"calendar")}${info("Email",s.email,"envelope")}${info("Phone",s.phone,"phone-call")}</div></section><section class="panel"><div class="panel-head"><div><h2>Academic Placement</h2><p class="panel-kicker">Current batch and group assignment</p></div></div><div class="panel-body info-grid profile-academic">${info("Batch",s.batch_name,"layers")}${info("Batch Code",s.batch_code,"label")}${info("Group",s.group_name,"users-class")}${info("Record Status",s.status,"shield-check")}</div></section></div><section class="panel"><div class="panel-head"><div><h2>Notes</h2><p class="panel-kicker">Additional information saved with this student</p></div></div><div class="panel-body"><div class="notes-box">${s.notes?esc(s.notes):`<span class="muted">No notes have been added for this student.</span>`}</div></div></section><section class="panel"><div class="panel-head"><div><h2>Record Information</h2><p class="panel-kicker">System metadata for audit and support</p></div></div><div class="panel-body record-meta"><div><span>Created</span><strong>${esc((s.created_at||"").slice(0,19).replace("T"," ")||"—")}</strong></div><div><span>Last Updated</span><strong>${esc((s.updated_at||"").slice(0,19).replace("T"," ")||"—")}</strong></div><div><span>Internal ID</span><strong>#${id}</strong></div></div></section>`;
  return html(appPage({title:"Student Profile",user:ctx.user,settings:ctx.settings,active:"students",url:ctx.url,actions,content}));
});

const academic={
  batches:{title:"Batches",table:"batches",name:"name",extra:"code",view:"batches.view",manage:"batches.manage"},
  lecturers:{title:"Lecturers",table:"lecturers",name:"full_name",extra:"email",view:"lecturers.view",manage:"lecturers.manage"},
  subjects:{title:"Subjects",table:"subjects",name:"name",extra:"code",view:"subjects.view",manage:"subjects.manage",relation:{column:"lecturer_id",table:"lecturers",display:"full_name",label:"Lecturer"}},
  groups:{title:"Groups",table:"groups_tbl",name:"name",extra:"",view:"groups.view",manage:"groups.manage",relation:{column:"batch_id",table:"batches",display:"name",label:"Batch"}}
};
async function academicGet(ctx,key){
  const c=academic[key],deny=needPerm(ctx,c.view);if(deny)return deny;
  const relationJoin=c.relation?` LEFT JOIN ${c.relation.table} rel ON rel.id=a.${c.relation.column}`:"";
  const relationSelect=c.relation?`,rel.${c.relation.display} relation_name`:"";
  const page=pageNumber(ctx.url.searchParams.get("page")),fetched=(await ctx.db.prepare(`SELECT a.*${relationSelect} FROM ${c.table} a${relationJoin} ORDER BY a.id DESC LIMIT ? OFFSET ?`).bind(ACADEMIC_PAGE_SIZE+1,(page-1)*ACADEMIC_PAGE_SIZE).all()).results||[],hasNext=fetched.length>ACADEMIC_PAGE_SIZE,rows=fetched.slice(0,ACADEMIC_PAGE_SIZE);
  const editId=intId(ctx.url.searchParams.get("edit")),edit=editId?await ctx.db.prepare(`SELECT * FROM ${c.table} WHERE id=?`).bind(editId).first():null;
  const relationRows=c.relation?(await ctx.db.prepare(`SELECT id,${c.relation.display} label FROM ${c.relation.table} WHERE status='ACTIVE' ORDER BY ${c.relation.display}`).all()).results||[]:[];
  const csrf=csrfFor(ctx.request);
  const body=rows.map(r=>`<tr><td><strong>${esc(r[c.name])}</strong></td>${c.extra?`<td>${esc(r[c.extra]||"—")}</td>`:""}${c.relation?`<td>${esc(r.relation_name||"—")}</td>`:""}<td>${badge(r.status)}</td><td>${can(ctx.user,c.manage)?`<a class="btn soft small" href="/${key}?edit=${r.id}">Edit</a>`:""}</td></tr>`).join("");
  const form=can(ctx.user,c.manage)?`<div class="panel"><div class="panel-head"><h2>${edit?"Edit":"Add"} Record</h2></div><div class="panel-body"><form method="post" class="grid two">${csrfField(csrf.token)}<input type="hidden" name="id" value="${edit?.id||""}"><label><span>Name *</span><input name="name" maxlength="150" required value="${esc(edit?.[c.name]||"")}"></label>${c.extra?`<label><span>${c.extra==="email"?"Email":"Code"}</span><input ${c.extra==="email"?'type="email" autocomplete="email"':""} name="extra" maxlength="${c.extra==="email"?254:100}" value="${esc(edit?.[c.extra]||"")}"></label>`:""}${c.relation?`<label><span>${esc(c.relation.label)}</span><select name="relation_id"><option value="">—</option>${relationRows.map(r=>`<option value="${r.id}" ${selected(edit?.[c.relation.column],r.id)}>${esc(r.label)}</option>`).join("")}</select></label>`:""}<label><span>Status</span><select name="status"><option ${selected(edit?.status||"ACTIVE","ACTIVE")}>ACTIVE</option><option ${selected(edit?.status,"INACTIVE")}>INACTIVE</option></select></label><div class="span2 actions"><button class="btn primary" type="submit">Save</button>${edit?`<a class="btn soft" href="/${key}">Cancel</a>`:""}</div></form></div></div>`:"";
  const extraHead=c.extra?`<th>${esc(c.extra==="email"?"Email":"Code")}</th>`:"",relationHead=c.relation?`<th>${esc(c.relation.label)}</th>`:"",colspan=3+(c.extra?1:0)+(c.relation?1:0);
  const pageUrl=new URL(ctx.url.toString());pageUrl.searchParams.delete("edit");
  const content=`${form}<div class="panel"><div class="table-wrap"><table><thead><tr><th>Name</th>${extraHead}${relationHead}<th>Status</th><th><span class="small">Actions</span></th></tr></thead><tbody>${body||`<tr><td colspan="${colspan}" class="empty">No records yet.</td></tr>`}</tbody></table></div></div>${pagination(pageUrl,page,hasNext)}`;
  return withCsrf(html(appPage({title:c.title,user:ctx.user,settings:ctx.settings,active:key,url:ctx.url,content})),csrf);
}
async function academicPost(ctx,key){
  const c=academic[key],deny=needPerm(ctx,c.manage);if(deny)return deny;const b=await readForm(ctx.request);if(!checkCsrf(ctx.request,b))return csrfFail(`/${key}`);
  const parsed=academicInput(b,{extra:c.extra,relation:c.relation});if(parsed.errors.length)return redirect(`/${key}?msg=${encodeURIComponent(parsed.errors.join(" "))}&type=error`);
  const {name,extraValue,status,relationId}=parsed.value,id=intId(b.id),ts=nowIso();
  if(c.relation&&relationId){const exists=await ctx.db.prepare(`SELECT id FROM ${c.relation.table} WHERE id=?`).bind(relationId).first();if(!exists)return redirect(`/${key}?msg=${encodeURIComponent(`${c.relation.label} not found.`)}&type=error`)}
  const columns=[c.name],values=[name];if(c.extra){columns.push(c.extra);values.push(extraValue)}if(c.relation){columns.push(c.relation.column);values.push(relationId)}columns.push("status");values.push(status);
  try{
    if(id){const existing=await ctx.db.prepare(`SELECT id FROM ${c.table} WHERE id=?`).bind(id).first();if(!existing)return redirect(`/${key}?msg=Record+not+found&type=error`);const set=columns.map(column=>`${column}=?`).join(",");await ctx.db.prepare(`UPDATE ${c.table} SET ${set},updated_at=? WHERE id=?`).bind(...values,ts,id).run();await audit(ctx.db,ctx.user.id,`${key.toUpperCase()}_UPDATE`,key,id,name)}
    else{const placeholders=columns.map(()=>"?").join(",");const r=await ctx.db.prepare(`INSERT INTO ${c.table}(${columns.join(",")},created_at,updated_at) VALUES(${placeholders},?,?)`).bind(...values,ts,ts).run();await audit(ctx.db,ctx.user.id,`${key.toUpperCase()}_CREATE`,key,r.meta?.last_row_id||"",name)}
    return redirect(`/${key}?msg=Saved`);
  }catch(error){const ref=operationError(`${key.toUpperCase()}_SAVE`,error);return redirect(`/${key}?msg=${encodeURIComponent(`Could not save. Reference ${ref}`)}&type=error`)}
}
for(const key of Object.keys(academic)){router.add("GET",`/${key}`,ctx=>academicGet(ctx,key));router.add("POST",`/${key}`,ctx=>academicPost(ctx,key))}

