const ROLE_LEVEL = {VIEWER:1,DATA_ENTRY:2,ADMIN:3,OWNER:4};
function roleLevel(role){return ROLE_LEVEL[role]||0}
function roleBadge(role){return `<span class="badge role ${esc(String(role||"").toLowerCase())}">${esc(String(role||"").replaceAll("_"," "))}</span>`}
function formatDateTime(value){return value?esc(String(value).slice(0,19).replace("T"," ")):"—"}
function targetWithinRole(actor,target){if(!actor||!target)return false;if(actor.role==="OWNER")return true;return target.role!=="OWNER"&&roleLevel(target.role)<=roleLevel(actor.role)}
function canManageTarget(actor,target){return Boolean(actor&&target&&can(actor,"users.manage")&&targetWithinRole(actor,target))}
function canAssignRole(actor,role){if(actor?.role==="OWNER")return USER_ROLES.includes(role);return role!=="OWNER"&&roleLevel(role)<=roleLevel(actor?.role)}
function editablePermission(actor,permission){return actor?.role==="OWNER"||Boolean(actor?.permissions?.has(permission))}
