function userForm(actor,u,set,csrf,isNew=false){const defaults=roleDefaultsData();return `<form method="post" class="grid two user-manage-form" data-user-form data-original-role="${esc(u.role||"VIEWER")}" data-original-status="${esc(u.status||"ACTIVE")}" data-role-defaults="${defaults}">${csrfField(csrf)}<label><span>Full Name *</span><input name="full_name" required maxlength="120" autocomplete="name" value="${esc(u.full_name||"")}"></label><label><span>Email *</span><input type="email" name="email" required maxlength="254" autocomplete="email" value="${esc(u.email||"")}"></label><label><span>Phone</span><input name="phone" maxlength="40" autocomplete="tel" inputmode="tel" value="${esc(u.phone||"")}"></label><label><span>Role</span><select name="role" data-user-role>${roleOptions(actor,u.role||"VIEWER")}</select></label><label><span>Status</span><select name="status"><option value="ACTIVE" ${selected(u.status||"ACTIVE","ACTIVE")}>ACTIVE</option><option value="DISABLED" ${selected(u.status,"DISABLED")}>DISABLED</option></select></label>${isNew?`<label><span>Initial Password *</span><input type="password" name="password" minlength="8" maxlength="128" autocomplete="new-password" required></label>`:""}<div class="span2 permission-editor"><div class="permission-editor-head"><div><h3>Effective Permissions</h3><p class="small muted">Role defaults are inherited. Only differences are stored as user overrides.</p></div><button class="btn soft small" type="button" data-reset-role-defaults>Reset to Role Defaults</button></div>${permissionGroups(set,actor,{role:u.role||"VIEWER"})}</div><div class="span2 actions"><button class="btn primary" type="submit">Save User</button><a class="btn soft" href="${u.id?`/users/${u.id}`:"/users"}">Cancel</a></div></form>`}

