router.add("POST","/settings",async ctx=>{
  const deny=needPerm(ctx,"settings.manage");if(deny)return deny;const b=await readForm(ctx.request);if(!checkCsrf(ctx.request,b))return csrfFail("/settings");
  const parsed=settingsInput(b);if(parsed.errors.length)return redirect(`/settings?msg=${encodeURIComponent(parsed.errors.join(" "))}&type=error`);
  const ts=nowIso(),{organizationName,supportEmail}=parsed.value;
  await ctx.db.batch([
    ctx.db.prepare("INSERT INTO settings(key,value,updated_at) VALUES('organization_name',?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at").bind(organizationName,ts),
    ctx.db.prepare("INSERT INTO settings(key,value,updated_at) VALUES('support_email',?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at").bind(supportEmail,ts)
  ]);
  invalidateSettingsCache(ctx.db);await audit(ctx.db,ctx.user.id,"SETTINGS_UPDATE","settings","","");return redirect("/settings?msg=Settings+saved");
});

export default{
  async fetch(request,env){
    try{
      const url=new URL(request.url),publicPaths=["/assets/app.css","/assets/app.js","/version","/health"];
      if(publicPaths.includes(url.pathname)){
        const res=await router.handle(request,{request,env,url});if(res)return res;
        const methods=router.methodsFor(url.pathname);if(methods.length)return methodNotAllowed({request,env,url,user:null,settings:{}},methods);
        return text("Not found",404);
      }
      if(!env.DB)return html(authPage({title:"Database Not Connected",subtitle:"This project needs a Cloudflare D1 binding named DB.",content:`<div class="notice error" role="alert">Redeploy using the included wrangler.jsonc so Cloudflare can provision or bind D1.</div>`,version:APP_VERSION}),500);
      const ctx=await context(request,env),res=await router.handle(request,ctx);if(res)return res;
      const methods=router.methodsFor(url.pathname);if(methods.length)return methodNotAllowed(ctx,methods);
      if(ctx.user)return html(appPage({title:"Not Found",user:ctx.user,settings:ctx.settings,active:"",url:ctx.url,content:`<div class="panel"><div class="panel-body"><h2>404</h2><p class="muted">The requested page does not exist.</p></div></div>`}),404);
      return html(authPage({title:"Not Found",content:`<a class="btn soft" href="/">Return Home</a>`,version:APP_VERSION}),404);
    }catch(error){
      const id=crypto.randomUUID();console.error("Unhandled error",id,error?.stack||error);
      return html(authPage({title:"Something went wrong",subtitle:`Request ID: ${id}`,content:`<div class="notice error" role="alert">The request could not be completed. Check Cloudflare Logs using the Request ID above.</div><a class="btn soft" href="/">Return Home</a>`,version:APP_VERSION}),500);
    }
  }
};
